CREATE TABLE IF NOT EXISTS `ai_model_log`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `model_name` varchar(50) NULL DEFAULT NULL,
  `api_endpoint` varchar(255) NULL DEFAULT NULL,
  `request_time` TIMESTAMP NULL DEFAULT NULL,
  `response_time` int NULL DEFAULT NULL,
  `status` TINYINT NULL DEFAULT NULL,
  `error_message` CLOB NULL,
  PRIMARY KEY (`id`)
);

CREATE TABLE IF NOT EXISTS `doctor`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `name` varchar(50) NOT NULL,
  `account` varchar(50) NULL DEFAULT NULL,
  `password` varchar(100) NULL DEFAULT NULL,
  `avatar` varchar(255) NULL DEFAULT NULL,
  `specialty` varchar(100) NULL DEFAULT NULL,
  `title` varchar(50) NULL DEFAULT NULL,
  `hospital` varchar(100) NULL DEFAULT NULL,
  `description` CLOB NULL,
  `status` TINYINT NULL DEFAULT 1,
  `consultation_count` int NULL DEFAULT 0,
  `create_time` TIMESTAMP NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
);

CREATE TABLE IF NOT EXISTS `doctor_consultation`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `patient_id` int NOT NULL,
  `doctor_id` int NOT NULL,
  `title` varchar(100) NULL DEFAULT NULL,
  `status` TINYINT NULL DEFAULT 0,
  `create_time` TIMESTAMP NULL DEFAULT NULL,
  `update_time` TIMESTAMP NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
);

CREATE TABLE IF NOT EXISTS `doctor_message`  (
  `id` int NOT NULL AUTO_INCREMENT,
